/**
 * /pages/MedicineImport.jsx
 * ---------------------------------------------------------------------------
 * Trang con của nhóm route `/medicine` (xem `children` trong router).
 * Demo import Excel: dùng chung logic với nút Import ở trang danh sách.
 */

import React, { useState } from 'react'
import { Card, Upload, Button, Space, Typography, Alert, message } from 'antd'
import { InboxOutlined, DownloadOutlined } from '@ant-design/icons'

import api from '@/model/api'
import { useI18n } from '@/lang'

const { Paragraph, Text } = Typography

const MedicineImport = () => {
  const { t } = useI18n()
  const [loading, setLoading] = useState(false)

  const handleUpload = async ({ file, onSuccess, onError }) => {
    setLoading(true)
    try {
      // Demo: giả lập upload, thực tế gọi: await api.medicineApi.importExcel(file)
      await new Promise((r) => setTimeout(r, 600))
      message.success(t('Import thành công'))
      onSuccess?.({})
    } catch (e) {
      onError?.(e)
    } finally {
      setLoading(false)
    }
  }

  const handleDownloadTemplate = async () => {
    try {
      // Demo: tạo file mẫu ngay trên trình duyệt
      const csv = 'code,name,unit,price,expiry\nMED001,Paracetamol 500mg,Hộp,25000,2026-12-31'
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'medicine-template.csv'
      a.click()
      URL.revokeObjectURL(url)
    } catch (e) {
      console.error(e)
    }
  }

  return (
    <Card size="small">
      <Alert
        type="info"
        showIcon
        className="mb-16"
        message={t('Import danh mục thuốc từ file Excel')}
        description={
          <span>
            {t('File cần có các cột:')} <Text code>code, name, unit, price, expiry</Text>
          </span>
        }
      />

      <Upload.Dragger
        accept=".xlsx,.xls,.csv"
        showUploadList={false}
        customRequest={handleUpload}
        disabled={loading}
      >
        <p className="ant-upload-drag-icon">
          <InboxOutlined />
        </p>
        <p className="ant-upload-text">
          {t('Kéo thả file vào đây hoặc bấm để chọn file')}
        </p>
        <p className="ant-upload-hint">{t('Hỗ trợ .xlsx, .xls, .csv')}</p>
      </Upload.Dragger>

      <Space className="mt-16">
        <Button icon={<DownloadOutlined />} onClick={handleDownloadTemplate}>
          {t('Tải file mẫu')}
        </Button>
      </Space>

      <Paragraph type="secondary" className="medicine-import-note">
        {t('Trang này là route con của /medicine — xem `children` trong src/router/index.jsx')}
      </Paragraph>
    </Card>
  )
}

export default MedicineImport
